
const CATEGORY_ACCORDION_IDS=["shopDetails","barDetails","hotelDetails","restaurantDetails","leisureDetails","serviceDetails","transportDetails"];
function closeOtherCategoryAccordions(keepId=""){
  CATEGORY_ACCORDION_IDS.forEach(id=>{
    const el=document.getElementById(id);
    if(el&&id!==keepId)el.open=false;
  });
}
function closeAllCategoryAccordions(resetAll=false){
  closeOtherCategoryAccordions("");
  if(resetAll){
    active="Tous";
    activeTransport=null;
    activeShop=null;
    activeService=null;
    activeLeisure=null;
    activeRestaurant=null;
    activeHotel=null;
    activeBar=null;
    document.querySelectorAll("#shopTypes .category,#barTypes .category,#hotelTypes .category,#restaurantTypes .category,#leisureTypes .category,#serviceTypes .category,#transportTypes .category").forEach(x=>x.setAttribute("aria-pressed","false"));
    if(typeof render==="function")render();
  }
}
function setupCategoryAccordions(){
  const top=document.getElementById("categories");
  if(top){
    top.style.display="none";
    top.setAttribute("aria-hidden","true");
  }
  CATEGORY_ACCORDION_IDS.forEach(id=>{
    const el=document.getElementById(id);
    if(!el)return;
    el.hidden=false;
    el.removeAttribute("aria-hidden");
    el.open=false;
    el.addEventListener("toggle",()=>{
      if(el.open)closeOtherCategoryAccordions(id);
    });
  });
}
