const STORAGE_KEY="libcomlair-proposals-v13";
function escapeHTML(value){return String(value??"").replace(/[&<>"\']/g,ch=>({"&":"&amp;","<":"&lt;",">":"&gt;","\"":"&quot;","\'":"&#39;"}[ch]))}
const accessibilityProfileFields={
  accessMobility:["Accès en fauteuil roulant","Entrée sans marche","Ascenseur","Toilettes adaptées","Stationnement PMR"],
  accessVisual:["Guidage tactile","Bandes d’éveil à la vigilance","Balises sonores","Braille ou relief"],
  accessHearing:["Information visuelle","Boucle magnétique"],
  accessCognitive:["Signalétique simplifiée","Orientation facilitée"],
  accessAssistance:["Personnel disponible","Assistance sur demande"]
};
const accessProfileOrder={mobility:"accessMobility",vision:"accessVisual",hearing:"accessHearing",cognitive:"accessCognitive",assistance:"accessAssistance"};
function currentAccessNeeds(){try{const v=JSON.parse(localStorage.getItem("libcomlair-access-profile-v1")||"null");return v&&Array.isArray(v.needs)?v.needs:[]}catch{return []}}
function renderAccessibilityProfile(place){
  const known=place&&place.geoapify?[...(Array.isArray(place.access)?place.access:[])]:[...(Array.isArray(place&&place.access)?place.access:[]),...(Array.isArray(place&&place.details)?place.details:[])];
  const selected=currentAccessNeeds();
  const profile=document.getElementById("accessibilityProfile");
  if(profile){
    const sections=[...profile.querySelectorAll(":scope > section")];
    const ids=selected.map(x=>accessProfileOrder[x]).filter(Boolean);
    sections.sort((a,b)=>{const ai=ids.indexOf(a.querySelector("ul")?.id),bi=ids.indexOf(b.querySelector("ul")?.id);return (ai<0?999:ai)-(bi<0?999:bi)});
    sections.forEach(section=>profile.appendChild(section));
  }
  Object.entries(accessibilityProfileFields).forEach(([id,labels])=>{
    const list=document.getElementById(id);if(!list)return;list.replaceChildren();
    labels.forEach(label=>{
      const li=document.createElement("li");
      const words=label.toLowerCase().split(/\s+/).filter(x=>x.length>4);
      const match=known.find(v=>typeof v==="string"&&words.some(w=>v.toLowerCase().includes(w)));
      li.textContent=(match?"✓ ":"— ")+label+" : "+(match?"information disponible — à vérifier":"Non renseigné");
      list.appendChild(li);
    });
    const section=list.closest("section");
    if(section)section.classList.toggle("access-priority",selected.some(x=>accessProfileOrder[x]===id));
  });
}
function safeHttpUrl(value){try{const u=new URL(String(value||""));return (u.protocol==="https:"||u.protocol==="http:")?u.href:null}catch(e){return null}}function safeMapPopup(name,address){const box=document.createElement("div");const strong=document.createElement("strong");strong.textContent=name||"";box.appendChild(strong);if(address){box.appendChild(document.createElement("br"));box.appendChild(document.createTextNode(address))}return box}
function proposalKey(p){return ((p.name||"").replace(" — Proposition à vérifier","").trim()+"|"+(p.city||"").trim()+"|"+(p.category||"")).toLowerCase()}
function cleanText(v,max=300){return typeof v==="string"?v.trim().slice(0,max):""}
function cleanStoredProposal(p){if(!p||typeof p!=="object"||Array.isArray(p))return null;const name=cleanText(p.name,160),city=cleanText(p.city,100);if(!name||!city)return null;const category=categories.includes(p.category)&&p.category!=="Tous"?p.category:"Services";const allowedAccess=Array.isArray(p.access)?p.access.filter(x=>accessibilityFilters.includes(x)).slice(0,accessibilityFilters.length):[];const lat=Number(p.lat),lon=Number(p.lon);const validCoords=Number.isFinite(lat)&&Number.isFinite(lon)&&lat>=-90&&lat<=90&&lon>=-180&&lon<=180;const details=Array.isArray(p.details)?p.details.filter(x=>typeof x==="string").map(x=>cleanText(x,500)).filter(Boolean).slice(0,20):[];return {userProposal:true,name,city,category,address:cleanText(p.address,250)||city,lat:validCoords?lat:null,lon:validCoords?lon:null,phone:cleanText(p.phone,60)||"Non renseigné",hours:"Non renseignés",website:cleanText(p.website,500)||"#",access:allowedAccess,details}}
function loadReports(){try{const raw=JSON.parse(localStorage.getItem("libcomlair-reports-v16")||"[]");if(!Array.isArray(raw)){localStorage.setItem("libcomlair-reports-v16","[]");return []}const statuses=new Set(["À vérifier","Toujours présent","Amélioration constatée","Résolu"]);const clean=raw.filter(x=>x&&typeof x==="object"&&!Array.isArray(x)).slice(-200).map(x=>{const place=cleanText(x.place,160),message=cleanText(x.message,1000),date=cleanText(x.date,40),status=statuses.has(x.status)?x.status:"À vérifier";let updates=Array.isArray(x.updates)?x.updates:[];updates=updates.filter(u=>u&&typeof u==="object"&&!Array.isArray(u)).slice(-20).map(u=>({message:cleanText(u.message,1000),date:cleanText(u.date,40),status:statuses.has(u.status)?u.status:status})).filter(u=>u.message);return {place,message,date,status,updates}}).filter(x=>x.place&&x.message);localStorage.setItem("libcomlair-reports-v16",JSON.stringify(clean));return clean}catch(e){try{localStorage.setItem("libcomlair-reports-v16","[]")}catch(_){}return []}}
function saveReports(reports){try{const statuses=new Set(["À vérifier","Toujours présent","Amélioration constatée","Résolu"]);const clean=(Array.isArray(reports)?reports:[]).filter(x=>x&&typeof x==="object"&&!Array.isArray(x)).slice(-200).map(x=>{const place=cleanText(x.place,160),message=cleanText(x.message,1000),date=cleanText(x.date,40),status=statuses.has(x.status)?x.status:"À vérifier";const updates=(Array.isArray(x.updates)?x.updates:[]).filter(u=>u&&typeof u==="object"&&!Array.isArray(u)).slice(-20).map(u=>({message:cleanText(u.message,1000),date:cleanText(u.date,40),status:statuses.has(u.status)?u.status:status})).filter(u=>u.message);return {place,message,date,status,updates}}).filter(x=>x.place&&x.message);localStorage.setItem("libcomlair-reports-v16",JSON.stringify(clean));return true}catch(e){return false}}
function loadReviews(){try{const raw=JSON.parse(localStorage.getItem("libcomlair-reviews-v18")||"[]");if(!Array.isArray(raw))return [];const clean=raw.filter(x=>x&&typeof x==="object"&&!Array.isArray(x)).slice(-500).map(x=>({placeKey:cleanText(x.placeKey,300),rating:Math.max(1,Math.min(5,Number(x.rating)||0)),comment:cleanText(x.comment,1000),date:cleanText(x.date,40)})).filter(x=>x.placeKey&&x.rating>=1&&x.rating<=5&&x.comment);localStorage.setItem("libcomlair-reviews-v18",JSON.stringify(clean));return clean}catch(e){return []}}
function saveReviews(v){try{const clean=(Array.isArray(v)?v:[]).filter(x=>x&&typeof x==="object"&&!Array.isArray(x)).slice(-500).map(x=>({placeKey:cleanText(x.placeKey,300),rating:Number(x.rating),comment:cleanText(x.comment,1000),date:cleanText(x.date,40)})).filter(x=>x.placeKey&&Number.isInteger(x.rating)&&x.rating>=1&&x.rating<=5&&x.comment);localStorage.setItem("libcomlair-reviews-v18",JSON.stringify(clean));return true}catch(e){return false}}
function loadFavorites(){try{const raw=JSON.parse(localStorage.getItem("libcomlair-favorites-v16")||"[]");if(!Array.isArray(raw)){localStorage.setItem("libcomlair-favorites-v16","[]");return []}const clean=[...new Set(raw.filter(x=>typeof x==="string").map(x=>cleanText(x,300)).filter(Boolean))].slice(0,500);localStorage.setItem("libcomlair-favorites-v16",JSON.stringify(clean));return clean}catch(e){try{localStorage.setItem("libcomlair-favorites-v16","[]")}catch(_){}return []}}
function loadSavedProposals(){try{const saved=JSON.parse(localStorage.getItem(STORAGE_KEY)||"[]");if(!Array.isArray(saved))return [];const seen={},clean=[];saved.slice(0,500).forEach(raw=>{const p=cleanStoredProposal(raw);if(!p)return;const k=proposalKey(p);if(k&&!seen[k]){seen[k]=true;clean.push(p)}});localStorage.setItem(STORAGE_KEY,JSON.stringify(clean));return clean}catch(e){return []}}
const NEARBY_STORAGE_KEY="libcomlair-geoapify-nearby-v3";const IDFM_STORAGE_KEY="libcomlair-idfm-nearby-v138";
function inferGeoapifyRestaurantType(categories){
  const cats=Array.isArray(categories)?categories.map(x=>String(x)):[];
  if(cats.some(x=>x.startsWith("catering.fast_food.pizza")||x.startsWith("catering.restaurant.pizza")))return "Pizzeria";
  if(cats.some(x=>x.startsWith("catering.cafe")))return "Café / salon de thé";
  if(cats.some(x=>x.startsWith("catering.fast_food")||x.startsWith("catering.food_court")))return "Fast-food";
  const worldCuisineKeys=new Set([
    "afghan","african","american","arab","argentinian","asian","austrian","balkan","bavarian","belgian","bolivian","brazilian",
    "caribbean","chinese","croatian","cuban","czech","danish","ethiopian","filipino","georgian","german","greek","hawaiian",
    "hungarian","indian","indonesian","international","irish","italian","jamaican","japanese","korean","latin_american",
    "lebanese","malay","malaysian","mediterranean","mexican","moroccan","nepalese","oriental","pakistani","persian","peruvian",
    "portuguese","russian","spanish","swedish","syrian","taiwanese","tex-mex","thai","turkish","ukrainian","uzbek","vietnamese","western"
  ]);
  const specific=cats.find(x=>x.startsWith("catering.restaurant."));
  if(specific){
    const key=specific.slice("catering.restaurant.".length).split(".")[0];
    return worldCuisineKeys.has(key)?"Cuisine du monde":"Restaurant traditionnel";
  }
  if(cats.some(x=>x.startsWith("catering.restaurant")))return "Restaurant traditionnel";
  return "";
}
function cleanNearbyPlace(p){if(!p||typeof p!=="object"||p.geoapify!==true)return null;const lat=Number(p.lat),lon=Number(p.lon);if(!Number.isFinite(lat)||!Number.isFinite(lon))return null;const name=String(p.name||"").trim(),city=String(p.city||"").trim();if(!name)return null;const norm=s=>s.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g,"").replace(/[^a-z0-9]+/g," ").trim();const nn=norm(name),nc=norm(city);const postalCity=/^\d{4,6}\b/.test(name)&&nc&&nn.endsWith(nc);const cityOnly=nc&&nn===nc;if(postalCity||cityOnly)return null;let transportType=String(p.transportType||"").trim();const cats=Array.isArray(p.geoapifyCategories)?p.geoapifyCategories:[];let restaurantType=String(p.restaurantType||"").trim();if(p.category==="Transports"&&!transportType&&window.LibcomlairTransport)transportType=window.LibcomlairTransport.inferGeoapifyTransportType(cats);if(p.category==="Restaurants"&&!restaurantType)restaurantType=inferGeoapifyRestaurantType(cats);return {...p,name,transportType,restaurantType,geoapify:true,lat,lon,access:Array.isArray(p.access)?p.access:[],details:Array.isArray(p.details)?p.details:[]}}
