async function loadNearbySourcesAutomatically(){
  const s=document.querySelector("#locationStatus");
  if(!navigator.geolocation)return;
  navigator.geolocation.getCurrentPosition(async pos=>{
    const lat=pos.coords.latitude,lon=pos.coords.longitude;
    userLat=lat;userLon=lon;
    const state=loadAutoRefreshState();
    const needGeo=!sourceIsFresh(state,"geoapifyTime",lat,lon);
    const needIdfm=!sourceIsFresh(state,"idfmTime",lat,lon);
    if(!needGeo&&!needIdfm){
      if(s)s.textContent="Les données locales ont été actualisées récemment.";
      return;
    }
    const base="https://libcomlair-backend.onrender.com";
    let geoUpdated=false,idfmUpdated=false,real=null,idfmStops=null;
    try{
      const requests=[];
      const keys=[];
      if(needGeo){keys.push("geo");requests.push(fetch(base+"/api/geoapify/nearby?lat="+encodeURIComponent(lat)+"&lon="+encodeURIComponent(lon)).catch(()=>null))}
      if(needIdfm){keys.push("idfm");requests.push(fetch(base+"/api/idfm/nearby?lat="+encodeURIComponent(lat)+"&lon="+encodeURIComponent(lon)).catch(()=>null))}
      const responses=await Promise.all(requests);
      for(let i=0;i<responses.length;i++){
        const response=responses[i],key=keys[i];
        if(!response||!response.ok)continue;
        const data=await response.json();
        if(key==="geo"){
          real=(Array.isArray(data.places)?data.places:[]).map(cleanNearbyPlace).filter(Boolean).filter(p=>p.category!=="Transports");
          geoUpdated=true;
        }else if(key==="idfm"){
          idfmStops=normalizeIdfmStops(data);
          idfmUpdated=true;
        }
      }
      if(geoUpdated){
        places=places.filter(p=>!p.geoapify);
        places.push(...real);
        saveNearbySaved(real);
        state.geoapifyTime=Date.now();
      }
      if(idfmUpdated){
        places=places.filter(p=>!p.idfm);
        places.push(...idfmStops);
        saveIdfmSaved(idfmStops);
        state.idfmTime=Date.now();
      }
      if(geoUpdated||idfmUpdated){
        state.lat=lat;state.lon=lon;saveAutoRefreshState(state);
        render();
        if(idfmUpdated)enrichAmbiguousIdfmStops(idfmStops,base);
        if(s){
          const parts=[];
          if(geoUpdated)parts.push(real.length+" lieux");
          if(idfmUpdated)parts.push(idfmStops.length+" arrêts de transport");
          s.textContent="Mise à jour automatique effectuée : "+parts.join(" et ")+".";
        }
      }else if(s&&(loadNearbySaved().length||loadIdfmSaved().length)){
        s.textContent="Les données enregistrées restent affichées. Une nouvelle actualisation sera tentée automatiquement.";
      }
    }catch(e){
      if(s&&(loadNearbySaved().length||loadIdfmSaved().length))s.textContent="Les données enregistrées restent affichées. Une nouvelle actualisation sera tentée automatiquement.";
    }
  },()=>{
    if(s&&(loadNearbySaved().length||loadIdfmSaved().length))s.textContent="Les données enregistrées restent affichées. Autorisez la localisation pour les actualiser automatiquement.";
  },{enableHighAccuracy:false,timeout:8000,maximumAge:300000});
}
loadNearbySourcesAutomatically();
