const accessEngine=window.LibcomlairAccessibility;
if(!accessEngine)throw new Error("LibcomlairAccessibility indisponible");
const ACCESS_PROFILE_KEY=accessEngine.KEY;
const accessWelcome=document.getElementById("accessWelcome");
function readAccessProfile(){return accessEngine.read()}
function saveAccessProfile(needs){return accessEngine.save(needs)}
function syncNeedFilters(needs){
  const wanted=new Set(accessEngine.filtersFor(needs));
  selectedAccess.clear();
  wanted.forEach(v=>selectedAccess.add(v));
  document.querySelectorAll("#accessFilters .category").forEach(btn=>btn.setAttribute("aria-pressed",wanted.has(btn.textContent)?"true":"false"));
}
function applyAccessProfileToPage(needs){
  document.documentElement.dataset.accessNeeds=needs.join(" ");
  const labels=accessEngine.labels;
  const summary=document.getElementById("activeAccessProfile");
  if(summary)summary.textContent=needs.length?"Profil actif : "+needs.map(n=>labels[n]).filter(Boolean).join(", "):"Aucune adaptation particulière sélectionnée.";
  const voiceNav=document.getElementById("visionVoiceControls");if(voiceNav)voiceNav.hidden=!needs.includes("vision");
  document.querySelectorAll('input[name="accessProfile"]').forEach(x=>x.checked=needs.includes(x.value));
  // Le profil personnel adapte la présentation mais ne filtre jamais automatiquement les lieux.
  // Les critères d’accessibilité ne deviennent des filtres que lorsque l’utilisateur les choisit explicitement.
  if(typeof selectedAccess!=="undefined"){ selectedAccess.clear(); document.querySelectorAll("#accessFilters .category").forEach(btn=>btn.setAttribute("aria-pressed","false")); }
  if(typeof render==="function")render();
}
function closeAccessWelcome(){if(!accessWelcome)return;accessWelcome.hidden=true;accessWelcome.setAttribute("hidden","");accessWelcome.style.display="none";const main=document.querySelector("main");if(main)main.scrollIntoView({behavior:"smooth",block:"start"})}

function visionIntroText(){
  const profile=readAccessProfile();
  const needs=profile?.needs||[];
  const labels={mobility:"mobilité",vision:"vision",hearing:"audition",cognitive:"compréhension et cognition",assistance:"assistance et accompagnement"};
  const selected=needs.map(x=>labels[x]).filter(Boolean).join(", ");
  const count=document.getElementById("resultsCount")?.textContent||"";
  return "Libcomlair. Profil actif : "+(selected||"aucune adaptation particulière")+". Vous pouvez rechercher un lieu, choisir une catégorie, consulter la liste des lieux ou modifier vos besoins d’accessibilité. Une rubrique Comment fonctionne Libcomlair explique les règles de classement et les informations à vérifier. "+count;
}
function removeVisionIntroFallback(){
  if(!window.__libcomlairVisionIntroFallback)return;
  const fn=window.__libcomlairVisionIntroFallback;
  ["pointerdown","touchstart","keydown","click"].forEach(type=>document.removeEventListener(type,fn,true));
  window.__libcomlairVisionIntroFallback=null;
}
function armVisionIntroFallback(){
  if(window.__libcomlairVisionIntroPlayed||window.__libcomlairVisionIntroFallback)return;
  const fn=()=>{
    if(window.__libcomlairVisionIntroPlayed){removeVisionIntroFallback();return}
    startVisionIntroSpeech(true);
  };
  window.__libcomlairVisionIntroFallback=fn;
  ["pointerdown","touchstart","keydown","click"].forEach(type=>document.addEventListener(type,fn,true));
}
function startVisionIntroSpeech(fromGesture=false){
  if(window.__libcomlairVisionIntroPlayed)return true;
  const engine=window.LibcomlairVoice;
  if(!engine||!engine.available)return false;
  const ok=engine.speak(visionIntroText(),{
    rate:0.9,
    onstart:()=>{
      window.__libcomlairVisionIntroPlayed=true;
      removeVisionIntroFallback();
    },
    onerror:()=>{if(!fromGesture)armVisionIntroFallback()}
  });
  if(!fromGesture)setTimeout(()=>{if(!window.__libcomlairVisionIntroPlayed)armVisionIntroFallback()},1600);
  return !!ok;
}
function maybeAutoReadVisionIntro(){
  if(window.__libcomlairVisionIntroPlayed)return;
  const p=readAccessProfile();
  if(!p||!Array.isArray(p.needs)||!p.needs.includes("vision"))return;
  setTimeout(()=>startVisionIntroSpeech(false),700);
}
const storedAccessProfile=readAccessProfile();
if(storedAccessProfile){applyAccessProfileToPage(storedAccessProfile.needs);closeAccessWelcome()}
document.getElementById("applyAccessProfile").addEventListener("click",()=>{
  const previous=readAccessProfile();
  const wasVision=!!(previous&&Array.isArray(previous.needs)&&previous.needs.includes("vision"));
  const needs=[...document.querySelectorAll('input[name="accessProfile"]:checked')].map(x=>x.value);
  const isVision=needs.includes("vision");
  if(saveAccessProfile(needs)){
    if(!isVision){
      removeVisionIntroFallback();
      if(window.LibcomlairVoice)window.LibcomlairVoice.cancel();else if("speechSynthesis" in window)window.speechSynthesis.cancel();
      window.__libcomlairVisionIntroPlayed=false;
    }else if(!wasVision){
      removeVisionIntroFallback();
      if(window.LibcomlairVoice)window.LibcomlairVoice.cancel();else if("speechSynthesis" in window)window.speechSynthesis.cancel();
      window.__libcomlairVisionIntroPlayed=false;
    }
    applyAccessProfileToPage(needs);
    closeAccessWelcome();
    document.getElementById("accessWelcomeStatus").textContent="";
    if(isVision)maybeAutoReadVisionIntro();
  }
});
document.getElementById("skipAccessProfile").addEventListener("click",()=>{saveAccessProfile([]);removeVisionIntroFallback();if(window.LibcomlairVoice)window.LibcomlairVoice.cancel();else if("speechSynthesis" in window)window.speechSynthesis.cancel();window.__libcomlairVisionIntroPlayed=false;applyAccessProfileToPage([]);closeAccessWelcome()});
