function setupVisionSpeechOutput(){
  const read=document.getElementById("visionReadPage"),stop=document.getElementById("visionStopReading"),test=document.getElementById("visionVoiceTest");
  if(!read||!stop)return;
  const engine=window.LibcomlairVoice;
  if(!engine||!engine.available){
    if(!("speechSynthesis" in window)){read.hidden=true;stop.hidden=true;if(test)test.hidden=true;return}
  }
  read.addEventListener("click",()=>{
    window.__libcomlairVisionIntroPlayed=false;
    removeVisionIntroFallback();
    startVisionIntroSpeech(true);
  });
  if(test)test.addEventListener("click",()=>{
    const status=document.getElementById("visionGuidePrompt");
    const fallback=window.LibcomlairFallbackVoice;
    if(status)status.textContent="Test de la voix de secours indépendante…";
    if(!fallback){
      if(status)status.textContent="⚠ Le moteur vocal de secours n’est pas chargé.";
      return;
    }
    const state=typeof fallback.status==="function"?fallback.status():null;
    if(!state||!state.ready){
      if(status)status.textContent=state&&state.loading?"Chargement de la voix française de secours… Appuyez de nouveau sur le bouton dès que ce message disparaît.":"⚠ La voix de secours n’est pas prête.";
      fallback.init?.().then(()=>{
        const current=document.getElementById("visionGuidePrompt");
        if(current)current.textContent="Voix française de secours prête. Appuyez sur Tester l’assistance vocale.";
      }).catch(e=>{
        const current=document.getElementById("visionGuidePrompt");
        if(current)current.textContent="⚠ Chargement de la voix de secours impossible : "+String(e&&e.message||e||"erreur")+".";
      });
      return;
    }
    const result=fallback.speakFromGesture("Assistance vocale Libcomlair activée.",{
      onstart:()=>{
        try{localStorage.setItem("libcomlair-voice-mode-v1","fallback")}catch(_){}
        if(status)status.textContent="✓ Voix de secours démarrée. Libcomlair utilisera désormais ce moteur vocal sur cet appareil.";
      },
      onerror:e=>{
        if(status)status.textContent="⚠ La voix de secours n’a pas pu être lue : "+String(e&&e.message||e||"erreur audio")+".";
      }
    });
    if(!result||!result.ok){
      if(status)status.textContent="⚠ Voix de secours indisponible : "+String(result&&result.reason||"non prête")+".";
    }
  });
  stop.addEventListener("click",()=>{
    removeVisionIntroFallback();
    if(engine)engine.cancel();else if("speechSynthesis" in window)window.speechSynthesis.cancel();
  });
  window.addEventListener("beforeunload",()=>{
    removeVisionIntroFallback();
    if(engine)engine.cancel();else if("speechSynthesis" in window)window.speechSynthesis.cancel();
  });
}
setupVisionSpeechOutput();

function setupTutorialSpeech(){
  const speeches={
    readLibcomlairTutorial:"Comment fonctionne Libcomlair. Les lieux proviennent de sources externes et peuvent aussi contenir des informations ajoutées ou vérifiées dans l'application. Les catégories et sous-catégories sont attribuées automatiquement lorsque les données permettent de les reconnaître. Libcomlair n'invente pas une information d'accessibilité. Lorsqu'elle n'est pas connue ou confirmée, elle est indiquée comme à vérifier. Les lieux, leur classement et leurs informations peuvent évoluer avec les mises à jour.",
    readShopTutorial:"Comment sont classés les magasins. Libcomlair utilise le type de commerce indiqué par les sources disponibles. Les magasins peuvent être classés en alimentation, vêtements, pharmacie ou parapharmacie, centre commercial, maison ou bricolage, électronique, beauté, ou culture et loisirs. Si le type précis n'est pas suffisamment identifié, le lieu reste dans tous les magasins.",
    readBarTutorial:"Comment sont classés les bars. Libcomlair utilise le type d'établissement indiqué dans les données disponibles. Les sous-catégories sont bar ou café, pub, bar à cocktails, bar musical, bar d'hôtel et bar-restaurant. Si le type précis n'est pas confirmé, l'établissement reste dans tous les bars.",
    readHotelTutorial:"Comment sont classés les hébergements. Libcomlair utilise la nature de l'hébergement indiquée par les sources. Les sous-catégories sont hôtel, appart hôtel, auberge ou hostel, chambre d'hôtes, résidence de tourisme, et camping ou hébergement de plein air. Si le type n'est pas suffisamment précis, le lieu reste dans tous les hébergements.",
    readRestaurantTutorial:"Comment sont classés les restaurants. Pizzeria, fast-food et café ou salon de thé sont attribués lorsque le type est clairement identifié. Cuisine du monde regroupe les cuisines identifiées par origine ou spécialité. Les restaurants génériques sont classés dans restaurant traditionnel. Gastronomique n'est pas attribué automatiquement sans information suffisamment fiable. Un établissement peut changer de sous-catégorie lorsque de nouvelles données plus précises deviennent disponibles.",
    readLeisureTutorial:"Comment sont classés les loisirs. Libcomlair classe les lieux selon l'activité principale indiquée par les sources. Les sous-catégories sont cinéma, musée, théâtre ou spectacle, bibliothèque ou médiathèque, sport, piscine, parc ou jardin, parc d'attractions et activités culturelles. Si l'activité n'est pas assez précise, le lieu reste dans tous les loisirs.",
    readServiceTutorial:"Comment sont classés les services. Libcomlair se base sur la fonction principale du lieu ou de l'organisme. Les sous-catégories sont santé ou soins, administrations ou services publics, banques, poste, services sociaux, aide à domicile, toilettes publiques accessibles, accueil ou information, et services spécialisés handicap. Si la fonction précise n'est pas connue, le lieu reste dans tous les services.",
    readTransportTutorial:"Comment sont classés les transports. Libcomlair utilise les informations des réseaux et sources de transport disponibles pour identifier le mode de transport et les arrêts ou gares. Les sous-catégories sont train ou gare, bus ou arrêt, métro, tramway, taxi ou transport adapté, et bateau ou ferry. Lorsque le mode exact n'est pas suffisamment identifié, le point de transport reste dans tous les transports. Les informations officielles peuvent évoluer avec les mises à jour des réseaux."
  };
  const buttons=Object.keys(speeches).map(id=>document.getElementById(id)).filter(Boolean);
  if(!buttons.length)return;
  if(!(window.LibcomlairVoice&&window.LibcomlairVoice.available)&&(!("speechSynthesis" in window)||typeof SpeechSynthesisUtterance!=="function")){
    buttons.forEach(button=>button.hidden=true);
    return;
  }
  function speak(text){
    const engine=window.LibcomlairVoice;
    if(engine&&engine.available){engine.speak(text,{rate:0.9});return}
    try{
      window.speechSynthesis.cancel();
      const u=new SpeechSynthesisUtterance(text);
      u.lang="fr-FR";
      u.rate=0.9;
      window.__libcomlairFallbackVoice=u;
      window.speechSynthesis.speak(u);
    }catch(_){}
  }
  Object.entries(speeches).forEach(([id,text])=>{
    const button=document.getElementById(id);
    if(button)button.addEventListener("click",()=>speak(text));
  });
}
setupTutorialSpeech();
maybeAutoReadVisionIntro();
